const secret = $env.AVERONAI_NOTIFY_SHARED_SECRET;
const provided = $input.first().json.headers['x-averonai-notify-secret'];
if (!provided || provided !== secret) {
  throw new Error('Invalid or missing x-averonai-notify-secret header');
}
return $input.all();

// Matches the payload shape posted by application/automation/send-weekly-report.ts's
// postWeeklyReport() — { companyName, recipient, newThisWeek, stats, revenue, funnel,
// topUncontacted }. If that function's payload shape changes, this node needs updating
// to match (there is no shared type between the two repos to keep this in sync
// automatically).
const n = (v) => Number(v).toLocaleString('en-US');
const money = (v) => `$${n(v)}`;
const minutes = (m) => {
  if (m === null || m === undefined) return 'no data yet';
  if (m < 60) return `${Math.round(m)}m`;
  if (m < 1440) return `${Math.round(m / 60)}h`;
  return `${Math.round(m / 1440)}d`;
};

const b = $input.first().json.body;
const rows = [
  ['New leads this week', n(b.newThisWeek)],
  ['Total leads', n(b.stats.total)],
  ['Buyers', `${n(b.stats.buyers)} (${n(b.stats.hotBuyers)} hot)`],
  ['Unassigned', n(b.stats.unassigned)],
  ['Contactable', n(b.stats.contactable)],
  ['High potential', n(b.stats.highPotential)],
  ['High score (80+)', n(b.stats.highScore)],
  ['Uncontacted 2h+', n(b.stats.uncontactedOver2h)],
  ['Median time to first touch', minutes(b.stats.medianTimeToFirstTouchMinutes)],
  ['Revenue this week', `${money(b.revenue.revenueLast30Days)} (${n(b.revenue.dealsLast30Days)} deals)`],
  ['Overall conversion to closed', `${Number(b.funnel.overallConversionPct).toFixed(1)}%`],
];
const tableRows = rows.map(([label, value]) =>
  `<tr><td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;color:#6b7280;\">${label}</td>` +
  `<td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;text-align:right;font-weight:600;\">${value}</td></tr>`
).join('');

const uncontacted = b.topUncontacted || [];
const uncontactedRows = uncontacted.map((l) =>
  `<tr><td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;\">${l.name}${l.where ? ` — ${l.where}` : ''}</td>` +
  `<td style=\"padding:6px 0;border-bottom:1px solid #e6e6e6;text-align:right;font-weight:600;\">${l.score}</td></tr>`
).join('');
const uncontactedSection = uncontacted.length === 0 ? '' :
  `<h3 style=\"font:600 13px/1.3 system-ui,sans-serif;margin:20px 0 8px;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;\">Top leads you haven't touched</h3>` +
  `<table style=\"width:100%;border-collapse:collapse;font:400 14px/1.6 system-ui,sans-serif;\">${uncontactedRows}</table>`;

const html = `<div style=\"max-width:480px;margin:0 auto;font-family:system-ui,sans-serif;\">` +
  `<h2 style=\"font:600 18px/1.3 system-ui,sans-serif;margin:0 0 12px;\">${b.companyName} — weekly lead report</h2>` +
  `<table style=\"width:100%;border-collapse:collapse;font:400 14px/1.6 system-ui,sans-serif;\">${tableRows}</table>${uncontactedSection}</div>`;

const textLines = [
  `${b.companyName} — weekly lead report`,
  '',
  ...rows.map(([label, value]) => `${label}: ${value}`),
  ...(uncontacted.length > 0 ? ['', "Top leads you haven't touched:", ...uncontacted.map((l) => `- ${l.name} — ${l.where} (${l.score})`)] : []),
];

return [{ json: { to: b.recipient, subject: `Weekly lead report — ${n(b.newThisWeek)} new this week`, html, text: textLines.join('\n') } }];
